import json
d=json.load(open('lg.json'))
def walk(o,out):
    if isinstance(o,dict):
        if o.get('type')=='text' and 'text' in o: out.append(o['text'])
        elif o.get('type')=='codeVoice': out.append('\`'+o.get('code','')+'\`')
        elif o.get('type')=='reference': out.append('['+str(o.get('identifier','')).split('/')[-1]+']')
        for k,v in o.items():
            if k not in ('text','code'): walk(v,out)
    elif isinstance(o,list):
        for i in o: walk(i,out)
out=[]
walk(d.get('abstract'),out); print('ABSTRACT:', ''.join(out)); 
print('METADATA:', json.dumps(d.get('metadata'),indent=1)[:800])
